async function load(){const [u,p,o,packageList]=await Promise.all([getAdminUsers().catch(async()=>{const me=await getPointAccount();return[{id:'ME',phone:username,role:'ADMIN',status:'ACTIVE',...me}]}),getFeaturePricing(),getAdminRechargeOrders().catch(()=>[]),getRechargePlans()]);users.value=u||[];pricing.value=p||[];orders.value=o||[];plans.value=(packageList||[]).filter(x=>[10,20,100].includes(Number(x.amount)))}function refresh(){load()}async function openUser(user){selectedUser.value=user;detailVisible.value=true;try{const detail=await getAdminUserDetail(user.id);selectedUser.value=detail.account||user;userTransactions.value=detail.transactions||[]}catch{userTransactions.value=[]}}function openAdjust(user){adjustUser.value=user;adjustForm.type='ADD';adjustForm.quantity=null;adjustForm.reason='';adjustForm.remark='';adjustVisible.value=true}async function submitAdjustment(){if(!adjustForm.quantity||!adjustForm.reason.trim()||!adjustForm.remark.trim())return ElMessage.warning('请完整填写数量、原因和备注');adjusting.value=true;try{await adjustAdminUserPoints(adjustUser.value.id,{...adjustForm});ElMessage.success('用户积分已调整并记录流水');adjustVisible.value=false;await load()}finally{adjusting.value=false}}async function savePrice(row){await updateFeaturePricing(row.featureCode,{costPoints:row.costPoints,enabled:row.enabled});ElMessage.success('功能价格已更新')}function paymentState(status){const value=String(status||'').toLowerCase();if(value==='paid')return{label:'支付成功',className:'success'};if(['refunded','refund'].includes(value))return{label:'退款',className:'refund'};return{label:'支付失败',className:'failed'}}
